1	/**
2	 * The cypress-realworld-app Witness calibration driver.
3	 *
4	 * The journey's selectors, routes and backend category were declared from the
5	 * application's own Cypress specs, never yet read off the live DOM+backend.
6	 * Pinning a stateful journey before the live surface has been measured is what
7	 * the TinyTranslator/Super-Productivity rounds spent passes undoing. This drives
8	 * ONE lane of the built production-static output against the application's REAL
9	 * Express-over-lowdb backend — the same host, static server and live-backend the
10	 * proof will use — and prints every measurement: the ordered steps and their
11	 * refusals, the recorded navigations, every request outcome bucketed by origin,
12	 * and the tracked-event counts.
13	 *
14	 * It publishes nothing, asserts nothing of its own, and is not part of any
15	 * receipt. Its only output is stdout. The backend is booted in the application's
16	 * own era runtime cell (Node 14.16.1), reseeded from its frozen snapshot before
17	 * the pass, exactly as the live-backend serving path reseeds.
18	 */
19	
20	import { type ChildProcess, spawn } from 'node:child_process';
21	import { readFileSync } from 'node:fs';
22	import { copyFile } from 'node:fs/promises';
23	import { get } from 'node:http';
24	import { basename, join, resolve } from 'pathe';
25	import { box, runBoxes } from '@async/witness';
26	import { joinURL, parseURL } from 'ufo';
27	import { canonicalize } from '../../../core/src/receipts/canonicalize.ts';
28	import { WITNESS_REACT_CYPRESS_RWA_ACTOR } from '../../../core/src/receipts/witness-react-cypress-rwa.ts';
29	import { witnessNodeFileSystem } from '../witness/node-filesystem.ts';
30	import { createPlaywrightWitnessHost } from '../witness/playwright-host.ts';
31	import type { WitnessObservedRequestOutcome } from '../witness/playwright-host.ts';
32	import { startStaticServer } from '../witness/real-app-run.ts';
33	
34	const root = resolve(import.meta.dirname, '../../../..');
35	const workRoot = join(root, '.versionless/work/react-cypress-rwa');
36	const eraNodeBin = join(
37		root,
38		'.versionless/cache/react-cypress-rwa-runtime/node-v14.16.1-darwin-x64/bin',
39	);
40	const eraYarnBin = join(root, '.versionless/cache/react-cypress-rwa-baseline/npm-global/bin');
41	const chromiumExecutable = join(
42		root,
43		'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
44	);
45	
46	const laneStaticRoot = {
47		baseline: join(workRoot, 'baseline/build-run1'),
48		migrated: join(workRoot, 'target/build-vite-run1'),
49	} as const;
50	
51	/** The application source lane the backend server is spawned from. */
52	const backendLaneRoot = join(workRoot, 'baseline');
53	const BACKEND_PORT = 3001;
54	
55	const VIEWPORT = { width: 1280, height: 900 } as const;
56	
57	const firstLine = (error: unknown): string =>
58		(error instanceof Error ? error.message : String(error)).split('\n')[0]!.trim();
59	
60	async function probeHealth(url: string): Promise<number | null> {
61		return await new Promise<number | null>((settle) => {
62			const request = get(url, (response) => {
63				const status = response.statusCode ?? null;
64				response.resume();
65				settle(status);
66			});
67			request.setTimeout(500, () => request.destroy());
68			request.on('error', () => settle(null));
69		});
70	}
71	
72	async function delay(ms: number): Promise<void> {
73		await new Promise<void>((settle) => void setTimeout(settle, ms));
74	}
75	
76	/**
77	 * Boot the application's own Express-over-lowdb backend in its era runtime, after
78	 * reseeding the mutable store from the frozen snapshot. The frontend addresses it
79	 * absolutely at `http://localhost:3001`, so the origin is fixed by the app.
80	 */
81	async function bootBackend(): Promise<{ origin: string; close(): Promise<void> }> {
82		await copyFile(
83			join(backendLaneRoot, 'data/database-seed.json'),
84			join(backendLaneRoot, 'data/database.json'),
85		);
86		const child: ChildProcess = spawn('yarn', ['start:api'], {
87			cwd: backendLaneRoot,
88			env: {
89				...process.env,
90				PATH: `${eraNodeBin}:${eraYarnBin}:${process.env.PATH ?? ''}`,
91				PORT: String(BACKEND_PORT),
92				SKIP_YARN_COREPACK_CHECK: '1',
93			},
94			stdio: 'ignore',
95		});
96		const origin = `http://localhost:${BACKEND_PORT}`;
97		const deadline = Date.now() + 45_000;
98		while (Date.now() < deadline) {
99			const status = await probeHealth(`http://127.0.0.1:${BACKEND_PORT}/checkAuth`);
100			if (status === 401) break;
101			await delay(250);
102		}
103		return {
104			origin,
105			close: async () => {
106				await new Promise<void>((settle) => {
107					child.once('exit', () => settle());
108					child.kill('SIGTERM');
109					setTimeout(() => {
110						if (child.exitCode === null && child.signalCode === null) child.kill('SIGKILL');
111					}, 2_000);
112				});
113			},
114		};
115	}
116	
117	function bucketRequests(
118		outcomes: readonly WitnessObservedRequestOutcome[],
119		staticOrigin: string,
120		backendOrigin: string,
121	): unknown {
122		const backend = new Map<string, { count: number; statuses: number[] }>();
123		const other: Array<{ method: string; url: string; status: number | null }> = [];
124		let staticCount = 0;
125		for (const outcome of outcomes) {
126			if (outcome.url.startsWith(staticOrigin)) {
127				staticCount += 1;
128				continue;
129			}
130			if (outcome.url.startsWith(backendOrigin)) {
131				const parsed = parseURL(outcome.url.slice(backendOrigin.length));
132				const path = parsed.pathname || '/';
133				const key = `${outcome.method} ${path}`;
134				const existing = backend.get(key);
135				if (existing === undefined) backend.set(key, { count: 1, statuses: [outcome.status ?? 0] });
136				else {
137					existing.count += 1;
138					if (!existing.statuses.includes(outcome.status ?? 0))
139						existing.statuses.push(outcome.status ?? 0);
140				}
141				continue;
142			}
143			other.push({ method: outcome.method, url: outcome.url, status: outcome.status });
144		}
145		return {
146			staticCount,
147			backend: [...backend.entries()]
148				.map(([key, value]) => ({ endpoint: key, ...value }))
149				.sort((left, right) => left.endpoint.localeCompare(right.endpoint)),
150			other,
151		};
152	}
153	
154	function pageSummary(receiptPath: string): unknown {
155		const receipt = JSON.parse(readFileSync(receiptPath, 'utf8')) as {
156			boxes?: Array<{ pages?: Array<Record<string, unknown>> }>;
157		};
158		const page = receipt.boxes?.[0]?.pages?.[0];
159		if (page === undefined) return null;
160		return {
161			navigations: (page.navigations as Array<{ url: string }> | undefined)?.map((navigation) => {
162				const parsed = parseURL(navigation.url);
163				return `${parsed.pathname}${parsed.hash}`;
164			}),
165			trackedEvents: Object.fromEntries(
166				Object.entries((page.trackedEvents as Record<string, unknown[]>) ?? {}).map(
167					([name, events]) => [name, events.length],
168				),
169			),
170			consoleErrors: (page.consoleMessages as Array<{ level: string }> | undefined)?.filter(
171				(message) => message.level === 'error',
172			).length,
173			pageErrors: (page.pageErrors as unknown[] | undefined)?.length,
174			failedRequests: page.failedRequests,
175		};
176	}
177	
178	export async function calibrateCypressRwaLane(lane: 'baseline' | 'migrated'): Promise<void> {
179		const actor = WITNESS_REACT_CYPRESS_RWA_ACTOR;
180		const staticRoot = laneStaticRoot[lane];
181		const receiptDir = join(root, '.versionless/stage/witness-react-cypress-rwa-calibrate', lane);
182		const backend = await bootBackend();
183		const staticServer = await startStaticServer(staticRoot, { profile: 'current-witness' });
184		const host = createPlaywrightWitnessHost({
185			chromiumExecutable,
186			contextProfile: 'current-witness',
187			viewport: VIEWPORT,
188		});
189		const steps: Array<{ name: string; outcome: string }> = [];
190		const probes: Record<string, number | string> = {};
191		let status = 'unknown';
192		let failure = '';
193		let receiptPath = '';
194		const definition = box(`cypress-rwa-calibrate-${lane}`, async (context) => {
195			const page = await context.browser.visit(joinURL(staticServer.origin, '/'));
196			await page.trackEvents('click', 'input', 'change', 'keydown', 'mouseover');
197			const step = async (name: string, fn: () => Promise<void>): Promise<void> => {
198				try {
199					await fn();
200					steps.push({ name, outcome: 'ok' });
201				} catch (error: unknown) {
202					steps.push({ name, outcome: `FAIL: ${firstLine(error)}` });
203				}
204				await delay(400);
205			};
206			// Parse the observed count out of a `count(sel, 0)` refusal so a probe never
207			// ends the pass; a genuinely absent selector reports 0.
208			const probe = async (selector: string): Promise<void> => {
209				try {
210					await context.expect.page.count(page, selector, 0);
211					probes[selector] = 0;
212				} catch (error: unknown) {
213					const line = firstLine(error);
214					const match = line.match(/observed (\d+)/);
215					probes[selector] = match ? Number(match[1]) : line;
216				}
217			};
218	
219			await probe('[data-test=signin-username]');
220			await probe('[data-test=signup]');
221			await step('click signup', () => page.click('[data-test=signup]'));
222			await probe('[data-test=signup-first-name]');
223			await step('type signup first', () =>
224				page.type('[data-test=signup-first-name]', actor.firstName, { redact: false }),
225			);
226			await step('type signup last', () =>
227				page.type('[data-test=signup-last-name]', actor.lastName, { redact: false }),
228			);
229			await step('type signup username', () =>
230				page.type('[data-test=signup-username]', actor.username, { redact: false }),
231			);
232			await step('type signup password', () =>
233				page.type('[data-test=signup-password]', actor.password, { redact: false }),
234			);
235			await step('type signup confirm', () =>
236				page.type('[data-test=signup-confirmPassword]', actor.password, { redact: false }),
237			);
238			await step('click signup-submit', () => page.click('[data-test=signup-submit]'));
239			await delay(1_200);
240			await probe('[data-test=signin-username]');
241			await step('type signin username', () =>
242				page.type('[data-test=signin-username]', actor.username, { redact: false }),
243			);
244			await step('type signin password', () =>
245				page.type('[data-test=signin-password]', actor.password, { redact: false }),
246			);
247			await step('click signin-submit', () => page.click('[data-test=signin-submit]'));
248			await delay(1_800);
249			// Onboarding
250			await probe('[data-test=user-onboarding-next]');
251			await probe('[data-test=user-onboarding]');
252			await step('click onboarding-next-1', () =>
253				page.click('[data-test=user-onboarding-next]', { timeoutMs: 6_000 }),
254			);
255			await probe('[data-test=bankaccount-bankName-input]');
256			await step('type bank name', () =>
257				page.type('[data-test=bankaccount-bankName-input]', 'Versionless Bank', { redact: false }),
258			);
259			await step('type routing', () =>
260				page.type('[data-test=bankaccount-routingNumber-input]', '987654321', { redact: false }),
261			);
262			await step('type account', () =>
263				page.type('[data-test=bankaccount-accountNumber-input]', '123456789', { redact: false }),
264			);
265			await step('click bankaccount-submit', () =>
266				page.click('[data-test=bankaccount-submit]', { timeoutMs: 6_000 }),
267			);
268			await delay(1_200);
269			await probe('[data-test=user-onboarding-next]');
270			await step('click onboarding-next-2', () =>
271				page.click('[data-test=user-onboarding-next]', { timeoutMs: 6_000 }),
272			);
273			await delay(1_000);
274			// Settings
275			await probe('[data-test=sidenav-user-settings]');
276			await step('click sidenav-user-settings', () =>
277				page.click('[data-test=sidenav-user-settings]', { timeoutMs: 6_000 }),
278			);
279			await probe('[data-test=user-settings-firstName-input]');
280			await step('type settings first', () =>
281				page.type('[data-test=user-settings-firstName-input]', actor.firstName, {
282					redact: false,
283					clear: true,
284				}),
285			);
286			await step('click user-settings-submit', () =>
287				page.click('[data-test=user-settings-submit]', { timeoutMs: 6_000 }),
288			);
289			await delay(1_000);
290			// Money movement
291			await probe('[data-test=nav-top-new-transaction]');
292			await step('click nav-top-new-transaction', () =>
293				page.click('[data-test=nav-top-new-transaction]', { timeoutMs: 6_000 }),
294			);
295			await probe('[data-test=user-list-search-input]');
296			await step('type search', () =>
297				page.type('[data-test=user-list-search-input]', 'a', { redact: false }),
298			);
299			await delay(1_500);
300			await probe('[data-test^=user-list-item-]');
301			await step('click first user-list-item', () =>
302				page.click('[data-test^=user-list-item-]', { timeoutMs: 6_000 }),
303			);
304			await probe('[data-test=transaction-create-amount-input]');
305			await step('type amount', () =>
306				page.type('[data-test=transaction-create-amount-input]', '15', { redact: false }),
307			);
308			await step('type description', () =>
309				page.type(
310					'[data-test=transaction-create-description-input]',
311					'versionless-proof-payment',
312					{ redact: false },
313				),
314			);
315			await probe('[data-test=transaction-create-submit-payment]');
316			await step('click submit-payment', () =>
317				page.click('[data-test=transaction-create-submit-payment]', { timeoutMs: 6_000 }),
318			);
319			await delay(1_800);
320			// Feed / filter
321			await probe('[data-test=sidenav-home]');
322			await step('click sidenav-home', () =>
323				page.click('[data-test=sidenav-home]', { timeoutMs: 6_000 }),
324			);
325			await probe('[data-test=nav-public-tab]');
326			await step('click nav-public-tab', () =>
327				page.click('[data-test=nav-public-tab]', { timeoutMs: 6_000 }),
328			);
329			await step('click nav-contacts-tab', () =>
330				page.click('[data-test=nav-contacts-tab]', { timeoutMs: 6_000 }),
331			);
332			await step('click nav-personal-tab', () =>
333				page.click('[data-test=nav-personal-tab]', { timeoutMs: 6_000 }),
334			);
335			await probe('[data-test=transaction-list-filter-amount-range-button]');
336			await probe('[data-test=transaction-list-filter-date-range-button]');
337			await step('click filter-amount-range', () =>
338				page.click('[data-test=transaction-list-filter-amount-range-button]', { timeoutMs: 6_000 }),
339			);
340			await delay(600);
341			// Notifications
342			await probe('[data-test=sidenav-notifications]');
343			await step('click sidenav-notifications', () =>
344				page.click('[data-test=sidenav-notifications]', { timeoutMs: 6_000 }),
345			);
346			await delay(1_200);
347			await context.receipt.capture('calibration-complete');
348		});
349		try {
350			const result = await runBoxes({
351				root: staticRoot,
352				boxes: [
353					{
354						file: join(staticRoot, 'versionless-runtime.box.ts'),
355						relativeFile: 'versionless-runtime.box.ts',
356						exportName: 'default',
357						box: definition,
358					},
359				],
360				receiptDir,
361				assertionTimeoutMs: 8_000,
362				fileSystem: witnessNodeFileSystem,
363				browser: host.browser,
364				headless: true,
365			});
366			status = result.status;
367			failure = result.boxes[0]?.error?.message ?? '';
368			receiptPath = result.receiptPath;
369		} finally {
370			await staticServer.close();
371			await backend.close();
372		}
373		process.stdout.write(
374			`${canonicalize({
375				lane,
376				status,
377				failure,
378				staticOrigin: staticServer.origin,
379				backendOrigin: backend.origin,
380				steps,
381				probes,
382				requests: bucketRequests(host.requestOutcomes(), staticServer.origin, backend.origin),
383				page: receiptPath === '' ? null : pageSummary(receiptPath),
384			})}\n`,
385		);
386	}
387	
388	export async function main(args = process.argv.slice(2)): Promise<void> {
389		const lane = args[0];
390		if (lane !== 'baseline' && lane !== 'migrated')
391			throw new Error('cypress-rwa calibration requires a lane: baseline or migrated');
392		await calibrateCypressRwaLane(lane);
393	}
394	
395	if (basename(process.argv[1] ?? '') === 'react-cypress-rwa-calibrate-run.ts')
396		main().catch((error: unknown) => {
397			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
398			process.exitCode = 1;
399		});
