/**
 * The cypress-realworld-app Witness calibration driver.
 *
 * The journey's selectors, routes and backend category were declared from the
 * application's own Cypress specs, never yet read off the live DOM+backend.
 * Pinning a stateful journey before the live surface has been measured is what
 * the TinyTranslator/Super-Productivity rounds spent passes undoing. This drives
 * ONE lane of the built production-static output against the application's REAL
 * Express-over-lowdb backend — the same host, static server and live-backend the
 * proof will use — and prints every measurement: the ordered steps and their
 * refusals, the recorded navigations, every request outcome bucketed by origin,
 * and the tracked-event counts.
 *
 * It publishes nothing, asserts nothing of its own, and is not part of any
 * receipt. Its only output is stdout. The backend is booted in the application's
 * own era runtime cell (Node 14.16.1), reseeded from its frozen snapshot before
 * the pass, exactly as the live-backend serving path reseeds.
 */

import { type ChildProcess, spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { copyFile } from 'node:fs/promises';
import { get } from 'node:http';
import { basename, join, resolve } from 'pathe';
import { box, runBoxes } from '@async/witness';
import { joinURL, parseURL } from 'ufo';
import { canonicalize } from '../../../core/src/receipts/canonicalize.ts';
import { WITNESS_REACT_CYPRESS_RWA_ACTOR } from '../../../core/src/receipts/witness-react-cypress-rwa.ts';
import { witnessNodeFileSystem } from '../witness/node-filesystem.ts';
import { createPlaywrightWitnessHost } from '../witness/playwright-host.ts';
import type { WitnessObservedRequestOutcome } from '../witness/playwright-host.ts';
import { startStaticServer } from '../witness/real-app-run.ts';

const root = resolve(import.meta.dirname, '../../../..');
const workRoot = join(root, '.versionless/work/react-cypress-rwa');
const eraNodeBin = join(
	root,
	'.versionless/cache/react-cypress-rwa-runtime/node-v14.16.1-darwin-x64/bin',
);
const eraYarnBin = join(root, '.versionless/cache/react-cypress-rwa-baseline/npm-global/bin');
const chromiumExecutable = join(
	root,
	'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
);

const laneStaticRoot = {
	baseline: join(workRoot, 'baseline/build-run1'),
	migrated: join(workRoot, 'target/build-vite-run1'),
} as const;

/** The application source lane the backend server is spawned from. */
const backendLaneRoot = join(workRoot, 'baseline');
const BACKEND_PORT = 3001;

const VIEWPORT = { width: 1280, height: 900 } as const;

const firstLine = (error: unknown): string =>
	(error instanceof Error ? error.message : String(error)).split('\n')[0]!.trim();

async function probeHealth(url: string): Promise<number | null> {
	return await new Promise<number | null>((settle) => {
		const request = get(url, (response) => {
			const status = response.statusCode ?? null;
			response.resume();
			settle(status);
		});
		request.setTimeout(500, () => request.destroy());
		request.on('error', () => settle(null));
	});
}

async function delay(ms: number): Promise<void> {
	await new Promise<void>((settle) => void setTimeout(settle, ms));
}

/**
 * Boot the application's own Express-over-lowdb backend in its era runtime, after
 * reseeding the mutable store from the frozen snapshot. The frontend addresses it
 * absolutely at `http://localhost:3001`, so the origin is fixed by the app.
 */
async function bootBackend(): Promise<{ origin: string; close(): Promise<void> }> {
	await copyFile(
		join(backendLaneRoot, 'data/database-seed.json'),
		join(backendLaneRoot, 'data/database.json'),
	);
	const child: ChildProcess = spawn('yarn', ['start:api'], {
		cwd: backendLaneRoot,
		env: {
			...process.env,
			PATH: `${eraNodeBin}:${eraYarnBin}:${process.env.PATH ?? ''}`,
			PORT: String(BACKEND_PORT),
			SKIP_YARN_COREPACK_CHECK: '1',
		},
		stdio: 'ignore',
	});
	const origin = `http://localhost:${BACKEND_PORT}`;
	const deadline = Date.now() + 45_000;
	while (Date.now() < deadline) {
		const status = await probeHealth(`http://127.0.0.1:${BACKEND_PORT}/checkAuth`);
		if (status === 401) break;
		await delay(250);
	}
	return {
		origin,
		close: async () => {
			await new Promise<void>((settle) => {
				child.once('exit', () => settle());
				child.kill('SIGTERM');
				setTimeout(() => {
					if (child.exitCode === null && child.signalCode === null) child.kill('SIGKILL');
				}, 2_000);
			});
		},
	};
}

function bucketRequests(
	outcomes: readonly WitnessObservedRequestOutcome[],
	staticOrigin: string,
	backendOrigin: string,
): unknown {
	const backend = new Map<string, { count: number; statuses: number[] }>();
	const other: Array<{ method: string; url: string; status: number | null }> = [];
	let staticCount = 0;
	for (const outcome of outcomes) {
		if (outcome.url.startsWith(staticOrigin)) {
			staticCount += 1;
			continue;
		}
		if (outcome.url.startsWith(backendOrigin)) {
			const parsed = parseURL(outcome.url.slice(backendOrigin.length));
			const path = parsed.pathname || '/';
			const key = `${outcome.method} ${path}`;
			const existing = backend.get(key);
			if (existing === undefined) backend.set(key, { count: 1, statuses: [outcome.status ?? 0] });
			else {
				existing.count += 1;
				if (!existing.statuses.includes(outcome.status ?? 0))
					existing.statuses.push(outcome.status ?? 0);
			}
			continue;
		}
		other.push({ method: outcome.method, url: outcome.url, status: outcome.status });
	}
	return {
		staticCount,
		backend: [...backend.entries()]
			.map(([key, value]) => ({ endpoint: key, ...value }))
			.sort((left, right) => left.endpoint.localeCompare(right.endpoint)),
		other,
	};
}

function pageSummary(receiptPath: string): unknown {
	const receipt = JSON.parse(readFileSync(receiptPath, 'utf8')) as {
		boxes?: Array<{ pages?: Array<Record<string, unknown>> }>;
	};
	const page = receipt.boxes?.[0]?.pages?.[0];
	if (page === undefined) return null;
	return {
		navigations: (page.navigations as Array<{ url: string }> | undefined)?.map((navigation) => {
			const parsed = parseURL(navigation.url);
			return `${parsed.pathname}${parsed.hash}`;
		}),
		trackedEvents: Object.fromEntries(
			Object.entries((page.trackedEvents as Record<string, unknown[]>) ?? {}).map(
				([name, events]) => [name, events.length],
			),
		),
		consoleErrors: (page.consoleMessages as Array<{ level: string }> | undefined)?.filter(
			(message) => message.level === 'error',
		).length,
		pageErrors: (page.pageErrors as unknown[] | undefined)?.length,
		failedRequests: page.failedRequests,
	};
}

export async function calibrateCypressRwaLane(lane: 'baseline' | 'migrated'): Promise<void> {
	const actor = WITNESS_REACT_CYPRESS_RWA_ACTOR;
	const staticRoot = laneStaticRoot[lane];
	const receiptDir = join(root, '.versionless/stage/witness-react-cypress-rwa-calibrate', lane);
	const backend = await bootBackend();
	const staticServer = await startStaticServer(staticRoot, { profile: 'current-witness' });
	const host = createPlaywrightWitnessHost({
		chromiumExecutable,
		contextProfile: 'current-witness',
		viewport: VIEWPORT,
	});
	const steps: Array<{ name: string; outcome: string }> = [];
	const probes: Record<string, number | string> = {};
	let status = 'unknown';
	let failure = '';
	let receiptPath = '';
	const definition = box(`cypress-rwa-calibrate-${lane}`, async (context) => {
		const page = await context.browser.visit(joinURL(staticServer.origin, '/'));
		await page.trackEvents('click', 'input', 'change', 'keydown', 'mouseover');
		const step = async (name: string, fn: () => Promise<void>): Promise<void> => {
			try {
				await fn();
				steps.push({ name, outcome: 'ok' });
			} catch (error: unknown) {
				steps.push({ name, outcome: `FAIL: ${firstLine(error)}` });
			}
			await delay(400);
		};
		// Parse the observed count out of a `count(sel, 0)` refusal so a probe never
		// ends the pass; a genuinely absent selector reports 0.
		const probe = async (selector: string): Promise<void> => {
			try {
				await context.expect.page.count(page, selector, 0);
				probes[selector] = 0;
			} catch (error: unknown) {
				const line = firstLine(error);
				const match = line.match(/observed (\d+)/);
				probes[selector] = match ? Number(match[1]) : line;
			}
		};

		await probe('[data-test=signin-username]');
		await probe('[data-test=signup]');
		await step('click signup', () => page.click('[data-test=signup]'));
		await probe('[data-test=signup-first-name]');
		await step('type signup first', () =>
			page.type('[data-test=signup-first-name]', actor.firstName, { redact: false }),
		);
		await step('type signup last', () =>
			page.type('[data-test=signup-last-name]', actor.lastName, { redact: false }),
		);
		await step('type signup username', () =>
			page.type('[data-test=signup-username]', actor.username, { redact: false }),
		);
		await step('type signup password', () =>
			page.type('[data-test=signup-password]', actor.password, { redact: false }),
		);
		await step('type signup confirm', () =>
			page.type('[data-test=signup-confirmPassword]', actor.password, { redact: false }),
		);
		await step('click signup-submit', () => page.click('[data-test=signup-submit]'));
		await delay(1_200);
		await probe('[data-test=signin-username]');
		await step('type signin username', () =>
			page.type('[data-test=signin-username]', actor.username, { redact: false }),
		);
		await step('type signin password', () =>
			page.type('[data-test=signin-password]', actor.password, { redact: false }),
		);
		await step('click signin-submit', () => page.click('[data-test=signin-submit]'));
		await delay(1_800);
		// Onboarding
		await probe('[data-test=user-onboarding-next]');
		await probe('[data-test=user-onboarding]');
		await step('click onboarding-next-1', () =>
			page.click('[data-test=user-onboarding-next]', { timeoutMs: 6_000 }),
		);
		await probe('[data-test=bankaccount-bankName-input]');
		await step('type bank name', () =>
			page.type('[data-test=bankaccount-bankName-input]', 'Versionless Bank', { redact: false }),
		);
		await step('type routing', () =>
			page.type('[data-test=bankaccount-routingNumber-input]', '987654321', { redact: false }),
		);
		await step('type account', () =>
			page.type('[data-test=bankaccount-accountNumber-input]', '123456789', { redact: false }),
		);
		await step('click bankaccount-submit', () =>
			page.click('[data-test=bankaccount-submit]', { timeoutMs: 6_000 }),
		);
		await delay(1_200);
		await probe('[data-test=user-onboarding-next]');
		await step('click onboarding-next-2', () =>
			page.click('[data-test=user-onboarding-next]', { timeoutMs: 6_000 }),
		);
		await delay(1_000);
		// Settings
		await probe('[data-test=sidenav-user-settings]');
		await step('click sidenav-user-settings', () =>
			page.click('[data-test=sidenav-user-settings]', { timeoutMs: 6_000 }),
		);
		await probe('[data-test=user-settings-firstName-input]');
		await step('type settings first', () =>
			page.type('[data-test=user-settings-firstName-input]', actor.firstName, {
				redact: false,
				clear: true,
			}),
		);
		await step('click user-settings-submit', () =>
			page.click('[data-test=user-settings-submit]', { timeoutMs: 6_000 }),
		);
		await delay(1_000);
		// Money movement
		await probe('[data-test=nav-top-new-transaction]');
		await step('click nav-top-new-transaction', () =>
			page.click('[data-test=nav-top-new-transaction]', { timeoutMs: 6_000 }),
		);
		await probe('[data-test=user-list-search-input]');
		await step('type search', () =>
			page.type('[data-test=user-list-search-input]', 'a', { redact: false }),
		);
		await delay(1_500);
		await probe('[data-test^=user-list-item-]');
		await step('click first user-list-item', () =>
			page.click('[data-test^=user-list-item-]', { timeoutMs: 6_000 }),
		);
		await probe('[data-test=transaction-create-amount-input]');
		await step('type amount', () =>
			page.type('[data-test=transaction-create-amount-input]', '15', { redact: false }),
		);
		await step('type description', () =>
			page.type(
				'[data-test=transaction-create-description-input]',
				'versionless-proof-payment',
				{ redact: false },
			),
		);
		await probe('[data-test=transaction-create-submit-payment]');
		await step('click submit-payment', () =>
			page.click('[data-test=transaction-create-submit-payment]', { timeoutMs: 6_000 }),
		);
		await delay(1_800);
		// Feed / filter
		await probe('[data-test=sidenav-home]');
		await step('click sidenav-home', () =>
			page.click('[data-test=sidenav-home]', { timeoutMs: 6_000 }),
		);
		await probe('[data-test=nav-public-tab]');
		await step('click nav-public-tab', () =>
			page.click('[data-test=nav-public-tab]', { timeoutMs: 6_000 }),
		);
		await step('click nav-contacts-tab', () =>
			page.click('[data-test=nav-contacts-tab]', { timeoutMs: 6_000 }),
		);
		await step('click nav-personal-tab', () =>
			page.click('[data-test=nav-personal-tab]', { timeoutMs: 6_000 }),
		);
		await probe('[data-test=transaction-list-filter-amount-range-button]');
		await probe('[data-test=transaction-list-filter-date-range-button]');
		await step('click filter-amount-range', () =>
			page.click('[data-test=transaction-list-filter-amount-range-button]', { timeoutMs: 6_000 }),
		);
		await delay(600);
		// Notifications
		await probe('[data-test=sidenav-notifications]');
		await step('click sidenav-notifications', () =>
			page.click('[data-test=sidenav-notifications]', { timeoutMs: 6_000 }),
		);
		await delay(1_200);
		await context.receipt.capture('calibration-complete');
	});
	try {
		const result = await runBoxes({
			root: staticRoot,
			boxes: [
				{
					file: join(staticRoot, 'versionless-runtime.box.ts'),
					relativeFile: 'versionless-runtime.box.ts',
					exportName: 'default',
					box: definition,
				},
			],
			receiptDir,
			assertionTimeoutMs: 8_000,
			fileSystem: witnessNodeFileSystem,
			browser: host.browser,
			headless: true,
		});
		status = result.status;
		failure = result.boxes[0]?.error?.message ?? '';
		receiptPath = result.receiptPath;
	} finally {
		await staticServer.close();
		await backend.close();
	}
	process.stdout.write(
		`${canonicalize({
			lane,
			status,
			failure,
			staticOrigin: staticServer.origin,
			backendOrigin: backend.origin,
			steps,
			probes,
			requests: bucketRequests(host.requestOutcomes(), staticServer.origin, backend.origin),
			page: receiptPath === '' ? null : pageSummary(receiptPath),
		})}\n`,
	);
}

export async function main(args = process.argv.slice(2)): Promise<void> {
	const lane = args[0];
	if (lane !== 'baseline' && lane !== 'migrated')
		throw new Error('cypress-rwa calibration requires a lane: baseline or migrated');
	await calibrateCypressRwaLane(lane);
}

if (basename(process.argv[1] ?? '') === 'react-cypress-rwa-calibrate-run.ts')
	main().catch((error: unknown) => {
		process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
		process.exitCode = 1;
	});

