295					missingAssets: run.servedStatic.missingAssets,
296					traversal: run.servedStatic.traversal,
297					byteIdentical: run.servedStatic.byteIdentical,
298					hmrControls: run.servedStatic.hmrControls,
299					liveBackend: run.servedStatic.liveBackend,
300				},
301				loopbackBackendPolicy: {
302					policy: run.loopbackBackend.policy,
303					backend: run.loopbackBackend.backend,
304					category: run.loopbackBackend.category,
305					outsideCategory: run.loopbackBackend.outsideCategory,
306					admitted: run.loopbackBackend.admitted,
307					successfulNonLoopback: run.loopbackBackend.successfulNonLoopback,
308				},
309				placeholders: run.placeholders,
310				successfulNonLoopback: run.successfulNonLoopback,
311			}),
312		);
313	}
314	
315	export function witnessReactCypressRwaDigest(receipt: WitnessReactCypressRwaReceipt): string {
316		const copy = structuredClone(receipt);
317		copy.integrity.canonicalDigest = '';
318		return sha256(canonicalize(copy));
319	}
