321	/**
322	 * Every string reachable in a value, so the redaction check can assert no seed
323	 * marker appears anywhere in the recorded evidence rather than in a hand-picked
324	 * subset of fields.
325	 */
326	function collectStrings(value: unknown, into: string[]): void {
327		if (typeof value === 'string') into.push(value);
328		else if (Array.isArray(value)) for (const item of value) collectStrings(item, into);
329		else if (value !== null && typeof value === 'object')
330			for (const item of Object.values(value)) collectStrings(item, into);
331	}
332	
333	function assertRedaction(run: WitnessReactCypressRwaRun, label: string): void {
334		const strings: string[] = [];
335		collectStrings(run, strings);
336		for (const text of strings)
337			for (const marker of WITNESS_REACT_CYPRESS_RWA_FORBIDDEN_MARKERS)
338				if (text.includes(marker))
339					throw new Error(`Cypress RWA Witness redaction leaked a seed marker: ${label}`);
340	}
341	
342	function assertServedStatic(served: WitnessReactCypressRwaServedStatic, label: string): void {
343		if (
344			served.transport !== 'isolated-bounded-loopback-production-static' ||
345			served.documentFallback !== 'index-only' ||
346			served.missingAssets !== '404' ||
347			served.traversal !== 'rejected' ||
348			!Number.isInteger(served.inventory?.files) ||
349			served.inventory.files < 1 ||
350			!sha256Digest(served.inventory.beforeSha256) ||
351			served.inventory.beforeSha256 !== served.inventory.afterSha256 ||
352			served.application?.path !== 'index.html' ||
353			!sha256Digest(served.application.beforeSha256) ||
354			served.application.beforeSha256 !== served.application.afterSha256 ||
355			served.byteIdentical !== true ||
356			served.hmrControls !== false ||
357			served.liveBackend?.backend !== 'live-loopback' ||
358			served.liveBackend.byteInventoryScope !== 'frontend-spa-dist' ||
359			served.liveBackend.rule !== WITNESS_LIVE_BACKEND_SERVED_RULE
360		)
361			throw new Error(`Cypress RWA Witness served-static differs: ${label}`);
362	}
363	
364	function assertLoopbackBackend(inventory: WitnessLoopbackBackendInventory, label: string): void {
365		if (
366			inventory?.policy !== 'live-first-party-loopback-backend' ||
367			inventory.backend !== 'live-loopback' ||
368			inventory.rule !== WITNESS_LOOPBACK_BACKEND_RULE ||
369			inventory.successfulNonLoopback !== 0 ||
370			!exact(inventory.outsideCategory, []) ||
371			!exact(inventory.category, WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY) ||
372			!Array.isArray(inventory.observed) ||
373			inventory.observed.length === 0 ||
374			inventory.admitted !== inventory.observed.reduce((sum, entry) => sum + entry.requests, 0)
375		)
