377		const declared = new Set(
378			WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY.map((entry) => `${entry.method} ${entry.path}`),
379		);
380		for (const observation of inventory.observed)
381			if (!declared.has(`${observation.method} ${observation.path}`))
382				throw new Error(`Cypress RWA Witness backend observation is undeclared: ${label}`);
383	}
