386		if (value === null || typeof value !== 'object' || Array.isArray(value))
387			throw new Error('Cypress RWA Witness receipt must be an object');
388		const receipt = value as WitnessReactCypressRwaReceipt;
389		const expectedRuns = new Set(['baseline:1', 'baseline:2', 'migrated:1', 'migrated:2']);
390		const behaviors = new Set<string>();
391		const semanticByLane = new Map<string, string>();
392		if (
393			receipt.schemaVersion !== WITNESS_REACT_CYPRESS_RWA_SCHEMA ||
394			receipt.result !== 'pass' ||
395			receipt.fixture !== REACT_CYPRESS_RWA_FIXTURE ||
396			receipt.application !== REACT_CYPRESS_RWA_APPLICATION ||
397			receipt.framework !== 'react' ||
398			!exact(receipt.source, REACT_CYPRESS_RWA_SOURCE) ||
399			!Array.isArray(receipt.runs) ||
400			receipt.runs.length !== 4 ||
401			!exact(receipt.placeholders, WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS) ||
402			!exact(receipt.backendCategory, WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY)
403		)
