405		for (const run of receipt.runs) {
406			const key = `${run.lane}:${run.pass}`;
407			if (
408				!expectedRuns.delete(key) ||
409				run.app !== REACT_CYPRESS_RWA_APPLICATION ||
410				run.framework !== 'react' ||
411				run.result !== 'pass' ||
412				run.cleanPage !== true ||
413				run.successfulNonLoopback !== 0 ||
414				run.witnessRecord.pageErrors !== 0 ||
415				!Array.isArray(run.interactions) ||
416				run.interactions.length === 0 ||
417				!Array.isArray(run.assertions) ||
418				run.assertions.length === 0 ||
419				!exact(run.routes, WITNESS_REACT_CYPRESS_RWA_ROUTES) ||
420				!exact(run.placeholders, WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS) ||
421				run.semanticDigest !== witnessReactCypressRwaRawDigest(run) ||
422				run.behaviorDigest !== witnessReactCypressRwaBehaviorDigest(run)
423			)
424				throw new Error(`Cypress RWA Witness run differs: ${key}`);
425			assertServedStatic(run.servedStatic, key);
426			assertLoopbackBackend(run.loopbackBackend, key);
427			assertRedaction(run, key);
428			const priorSemantic = semanticByLane.get(run.lane);
429			if (priorSemantic !== undefined && priorSemantic !== run.semanticDigest)
430				throw new Error(`Cypress RWA Witness pass-twice semantic digest differs: ${run.lane}`);
431			semanticByLane.set(run.lane, run.semanticDigest);
432			behaviors.add(run.behaviorDigest);
433		}
434		if (
435			expectedRuns.size !== 0 ||
436			behaviors.size !== 1 ||
437			receipt.determinism?.reseededFromSnapshotBeforeEachPass !== true ||
438			receipt.determinism.mintedValuesPlaceholdered !== true ||
439			receipt.determinism.rule !== WITNESS_JOURNEY_PLACEHOLDER_RULE ||
440			receipt.redaction?.policy !== 'no-seed-usernames-passwords-or-pii' ||
441			receipt.redaction.actorIsNonSeedCorpusIdentity !== true ||
442			!exact(receipt.redaction.forbiddenMarkers, WITNESS_REACT_CYPRESS_RWA_FORBIDDEN_MARKERS) ||
443			receipt.mutation?.intendedFailure !== true ||
444			receipt.mutation.failure !== 'witness-semantic-assertion' ||
445			receipt.mutation.lane !== 'migrated' ||
446			receipt.mutation.restoredByteIdentically !== true ||
447			receipt.mutation.restoredRun !== 'pass' ||
448			receipt.mutation.beforeSha256 !== receipt.mutation.afterRestoreSha256 ||
449			receipt.mutation.beforeSha256 === receipt.mutation.mutatedSha256 ||
450			!behaviors.has(receipt.mutation.restoredBehaviorDigest) ||
451			receipt.locality?.mode !== 'live-loopback-backend' ||
452			receipt.locality.successfulNonLoopback !== 0 ||
453			receipt.locality.osWideIsolation !== false ||
454			receipt.locality.rule !== WITNESS_LOOPBACK_BACKEND_RULE ||
455			!Array.isArray(receipt.nonclaims) ||
456			receipt.nonclaims.length === 0 ||
457			receipt.integrity?.algorithm !== 'sha256' ||
458			receipt.integrity.canonicalDigest !== witnessReactCypressRwaDigest(receipt)
459		)
460			throw new Error('Cypress RWA Witness integrity or determinism differs');
461		return receipt;
462	}
