66	/** A running live backend bound to a second bounded loopback origin. */
67	export type LiveBackendHandle = {
68		/** The `http://127.0.0.1:<port>` origin the application's server is bound to. */
69		origin: string;
70		/**
71		 * Restore the frozen seed and restart the server, so the next pass starts from
72		 * exactly the declared snapshot rather than inheriting the mutations the
73		 * previous pass made. A lowdb store is read at boot, so a re-seed is a
74		 * restart, not a live file swap.
75		 */
76		reseed(): Promise<void>;
77		/** Stop the server and release the loopback port. */
78		close(): Promise<void>;
79	};
