81	const DEFAULT_READY_TIMEOUT_MS = 30_000;
82	const HEALTH_POLL_INTERVAL_MS = 250;
83	
84	function backendOrigin(port: number): string {
85		return stringifyParsedURL({ protocol: 'http:', host: `127.0.0.1:${port}` });
