88	async function probeHealth(origin: string, path: string): Promise<number | null> {
89		return await new Promise<number | null>((resolvePromise) => {
90			const request = get(`${origin}${path}`, (response) => {
91				const status = response.statusCode ?? null;
92				response.resume();
93				resolvePromise(status);
94			});
95			request.setTimeout(HEALTH_POLL_INTERVAL_MS, () => request.destroy());
96			request.on('error', () => resolvePromise(null));
97		});
98	}
99	
100	async function delay(ms: number): Promise<void> {
101		await new Promise<void>((resolvePromise) => {
102			setTimeout(resolvePromise, ms);
103		});
104	}
105	
106	async function applySeed(laneRoot: string, spec: LiveBackendSpec): Promise<void> {
107		const copies = [
108			{ from: spec.seed.snapshot, to: spec.seed.store },
109			...(spec.prepare ?? []),
110		];
111		for (const copy of copies) {
112			const to = resolve(laneRoot, copy.to);
113			await mkdir(dirname(to), { recursive: true });
114			await copyFile(resolve(laneRoot, copy.from), to);
115		}
116	}
