118	function spawnBackend(laneRoot: string, spec: LiveBackendSpec): ChildProcess {
119		return spawn(spec.command, [...spec.args], {
120			cwd: resolve(laneRoot, spec.cwd ?? '.'),
121			env: { ...process.env, ...spec.env, PORT: String(spec.port) },
122			stdio: 'ignore',
123		});
124	}
125	
126	async function waitForHealth(origin: string, spec: LiveBackendSpec): Promise<void> {
127		const deadline = Date.now() + (spec.readyTimeoutMs ?? DEFAULT_READY_TIMEOUT_MS);
128		const okStatus = new Set(spec.health.okStatus);
129		while (Date.now() < deadline) {
130			const status = await probeHealth(origin, spec.health.path);
131			if (status !== null && okStatus.has(status)) return;
132			await delay(HEALTH_POLL_INTERVAL_MS);
133		}
134		throw new Error(`live backend did not become healthy at ${origin}${spec.health.path}`);
135	}
136	
137	async function stopProcess(child: ChildProcess): Promise<void> {
138		if (child.exitCode !== null || child.signalCode !== null) return;
139		await new Promise<void>((resolvePromise) => {
140			child.once('exit', () => resolvePromise());
141			child.kill('SIGTERM');
142			setTimeout(() => {
143				if (child.exitCode === null && child.signalCode === null) child.kill('SIGKILL');
144			}, 2_000);
145		});
146	}
147	
148	/**
149	 * Spawns the application's own server on a second bounded loopback origin,
150	 * having first restored its frozen seed. Generic: every value comes from the
151	 * declared {@link LiveBackendSpec}, so a stateful application is served by
152	 * declaring one, not by teaching the harness its name.
153	 */
154	export async function startLiveBackend(
155		laneRoot: string,
156		spec: LiveBackendSpec,
157	): Promise<LiveBackendHandle> {
158		const origin = backendOrigin(spec.port);
159		let child: ChildProcess | null = null;
160		const bringUp = async (): Promise<void> => {
161			if (child !== null) await stopProcess(child);
162			await applySeed(laneRoot, spec);
163			child = spawnBackend(laneRoot, spec);
164			await waitForHealth(origin, spec);
165		};
166		await bringUp();
167		return {
168			origin,
169			reseed: bringUp,
170			close: async () => {
171				if (child !== null) await stopProcess(child);
172				child = null;
173			},
174		};
175	}
176	
177	function originRelativePath(url: string, origin: string): string {
178		const rest = url.slice(origin.length);
179		const parsed = parseURL(rest.startsWith('/') ? rest : `/${rest}`);
180		return parsed.pathname || '/';
181	}
182	
183	const backendKey = (method: string, path: string): string => `${method} ${path}`;
184	
185	/**
186	 * Builds the live-backend request inventory for one run from the observed
187	 * request outcomes and the two bounded loopback origins.
188	 *
189	 * The static origin is ignored here — it has its own byte inventory — and every
190	 * request to the backend origin is counted in its own category by method and
191	 * origin-relative path. The non-loopback discipline is unweakened: a request to
192	 * anything that is neither loopback origin fails the run, and a backend endpoint
193	 * the journey did not declare lands in `outsideCategory`, which must stay empty.
194	 * `successfulNonLoopback` is fixed at 0 by construction, because nothing counted
195	 * here left the machine.
196	 */
197	export function buildLoopbackBackendInventory(
198		requestOutcomes: readonly WitnessObservedRequestOutcome[],
199		staticOrigin: string,
200		origin: string,
201		category: readonly WitnessLoopbackBackendCategoryEntry[],
202	): WitnessLoopbackBackendInventory {
203		const declared = new Set(category.map((entry) => backendKey(entry.method, entry.path)));
204		if (declared.size !== category.length)
205			throw new Error('live backend inventory repeats a declared endpoint');
206		const observations = new Map<string, WitnessLoopbackBackendObservation>();
207		const outside: WitnessLoopbackBackendCategoryEntry[] = [];
208		for (const outcome of requestOutcomes) {
209			if (outcome.url.startsWith(staticOrigin)) continue;
210			if (!outcome.url.startsWith(origin)) {
211				if (!isWitnessLoopbackUrl(outcome.url))
212					throw new Error(`live backend run reached a non-loopback origin: ${outcome.url}`);
213				throw new Error(`live backend run reached an unexpected loopback origin: ${outcome.url}`);
214			}
215			const path = originRelativePath(outcome.url, origin);
216			const key = backendKey(outcome.method, path);
217			if (!declared.has(key)) {
218				if (!outside.some((entry) => backendKey(entry.method, entry.path) === key))
219					outside.push({ method: outcome.method, path });
220				continue;
221			}
222			const existing = observations.get(key);
223			const status = outcome.status ?? 0;
224			if (existing === undefined)
225				observations.set(key, {
226					method: outcome.method,
227					path,
228					requests: 1,
229					statuses: [status],
230				});
231			else {
232				existing.requests += 1;
233				if (!existing.statuses.includes(status)) existing.statuses.push(status);
234			}
235		}
236		if (outside.length > 0)
237			throw new Error(
238				`live backend requests outside the declared category: ${JSON.stringify(outside)}`,
239			);
240		const observed = [...observations.values()].map((observation) => ({
241			...observation,
242			statuses: [...observation.statuses].sort((left, right) => left - right),
243		}));
244		observed.sort((left, right) =>
245			backendKey(left.method, left.path).localeCompare(backendKey(right.method, right.path)),
246		);
247		const observedKeys = new Set(observed.map((entry) => backendKey(entry.method, entry.path)));
248		const absent = category
249			.filter((entry) => !observedKeys.has(backendKey(entry.method, entry.path)))
250			.map((entry) => ({ method: entry.method, path: entry.path }));
251		return {
252			policy: 'live-first-party-loopback-backend',
253			backend: 'live-loopback',
254			rule: WITNESS_LOOPBACK_BACKEND_RULE,
255			category: category.map((entry) => ({ method: entry.method, path: entry.path })),
256			observed,
257			absent,
258			outsideCategory: [],
259			admitted: observed.reduce((sum, entry) => sum + entry.requests, 0),
260			successfulNonLoopback: 0,
261		};
262	}
263	
264	/** One minted value captured from a run, paired with the token that replaces it. */
265	export type WitnessCapturedMint = WitnessJourneyPlaceholderDeclaration & { value: string };
266	
267	/**
268	 * Replaces every occurrence of each declared minted value with its stable
269	 * placeholder token throughout a run's recorded journey evidence.
270	 *
271	 * This is the generic form of the HospitalRun `{created-patient-id}` idiom: a
272	 * stateful journey mints identifiers its server decides, captures them, and
273	 * declares the token each is normalized to. Only the captured values are
274	 * touched — the shape of the evidence is untouched — so two passes that minted
275	 * different identifiers normalize to identical evidence while a dropped step
276	 * still differs. Longer values are substituted first so a value that is a
277	 * substring of another cannot be half-replaced, and a token that already appears
278	 * literally in the un-normalized evidence is rejected as ambiguous.
279	 */
280	export function normalizeJourneyPlaceholders<T>(evidence: T, mints: readonly WitnessCapturedMint[]): T {
281		if (mints.length === 0) return structuredClone(evidence);
282		const serialized = JSON.stringify(evidence);
283		if (serialized === undefined)
284			throw new Error('journey evidence is not serializable for placeholder normalization');
285		let text = serialized;
286		const ordered = [...mints].sort((left, right) => right.value.length - left.value.length);
287		for (const mint of ordered) {
288			if (mint.value.length === 0 || mint.token.length === 0)
289				throw new Error('journey placeholder declares an empty value or token');
290			if (text.includes(mint.token))
291				throw new Error(`journey placeholder token collides with recorded evidence: ${mint.token}`);
292		}
293		for (const mint of ordered) text = text.split(mint.value).join(mint.token);
294		return JSON.parse(text) as T;
295	}
296	
297	/** The stateful application names this serving path admits, re-exported for callers. */
298	export const LIVE_BACKEND_STATEFUL_NAMES = WITNESS_REAL_APP_STATEFUL_NAMES;
