const describe = async (selector: string): Promise<unknown> =>
	await page.evaluate((sel: string) => {
		const element = document.querySelector(sel);
		if (element === null) return { present: false };
		const input = element.querySelector('input,textarea');
		return {
			present: true,
			tag: element.tagName.toLowerCase(),
			href: (element as HTMLAnchorElement).getAttribute?.('href') ?? null,
			hasNestedInput: input !== null,
			nestedInputId: input?.getAttribute('id') ?? null,
		};
	}, selector);

try {
	await page.goto(`${staticServer.origin}/`, { waitUntil: 'domcontentloaded' });
	await delay(2_000);
	await snapshot('initial');
	legs.push({ describe: 'signin-username', value: await describe('[data-test=signin-username]') });
	legs.push({ describe: 'signup-link', value: await describe('[data-test=signup]') });
	// Does React-Router navigation work at all? Try the link click, then a
	// direct client push, then a hard document navigation to /signup.
	await clickIfPresent('[data-test=signup]', 'click-signup');
	legs.push({ afterClickUrl: page.url() });
	await page.evaluate(() => window.history.pushState({}, '', '/signup'));
	await delay(1_500);
	await snapshot('after-pushState-signup');
	await page.goto(`${staticServer.origin}/signup`, { waitUntil: 'domcontentloaded' });
	await delay(2_000);
	await snapshot('after-hard-goto-signup');
	legs.push({
		describe: 'signup-first-name',
		value: await describe('[data-test=signup-first-name]'),
	});
	// Try filling the nested input of first-name to confirm the working selector.
	await typeIfPresent('[data-test=signup-first-name] input', actor.firstName, 'fill-first-nested');
} finally {

